import{_ as t,o as s,c as n,ai as e}from"./chunks/framework.BBSijY9B.js";const d=JSON.parse('{"title":"模板：会议助理","description":"会前备材料、会后出纪要和待办，跟进邮件一律先出草稿。","frontmatter":{"related":["/roles/managers","/templates/weekly-report"],"template":"meeting-assistant","title":"模板：会议助理","description":"会前备材料、会后出纪要和待办，跟进邮件一律先出草稿。","section":"templates","order":7,"role":"会议助理","type":"单 Bot 模板","tags":["模板","会议","纪要"],"sources":["https://cursor.com/docs/grok-bot/work","https://docs.x.ai/grok-bot/skills-routines-and-automations"],"wordCount":143,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"模板：会议助理 | WANGXXXL"}],["meta",{"property":"og:description","content":"会前备材料、会后出纪要和待办，跟进邮件一律先出草稿。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/templates/meeting-assistant"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/templates-meeting-assistant-7175b092ac.png"}],["meta",{"property":"og:image:alt","content":"模板：会议助理 · WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"模板：会议助理 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"会前备材料、会后出纪要和待办，跟进邮件一律先出草稿。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/templates-meeting-assistant-7175b092ac.png"}],["meta",{"name":"twitter:image:alt","content":"模板：会议助理 · WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/templates/meeting-assistant"}]]},"headers":[],"relativePath":"templates/meeting-assistant.md","filePath":"templates/meeting-assistant.md","lastUpdated":1792485206000}'),p={name:"templates/meeting-assistant.md"};function o(i,a,l,r,c,m){return s(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="模板-会议助理" tabindex="-1">模板：会议助理 <a class="header-anchor" href="#模板-会议助理" aria-label="Permalink to &quot;模板：会议助理&quot;">​</a></h1><ul><li><strong>角色</strong>：会议助理</li><li><strong>类型</strong>：单 Bot 模板</li><li><strong>需要的连接</strong>：日历、邮箱；可选网盘、Slack</li><li><strong>适合谁</strong>：会议多、经常会后忘记跟进的人</li></ul><h2 id="提示词" tabindex="-1">提示词 <a class="header-anchor" href="#提示词" aria-label="Permalink to &quot;提示词&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的岗位是&quot;会议助理&quot;。请记住以下规则：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【会前】（我说&quot;准备 XX 会议&quot;时）</span></span>
<span class="line"><span>- 整理会议基本信息：时间、参与人、目的。</span></span>
<span class="line"><span>- 汇总相关背景：最近相关邮件要点、上次会议纪要中的遗留事项。</span></span>
<span class="line"><span>- 给出建议议程和我需要提前想清楚的 3 个问题。</span></span>
<span class="line"><span>- 控制在一页以内。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【会后】（我上传录音、文字记录或口述要点时）</span></span>
<span class="line"><span>- 输出纪要：决议 / 待办（事项 + 负责人 + 截止日期）/ 待定问题。</span></span>
<span class="line"><span>- 负责人或日期不明确的待办，标注&quot;待确认&quot;，不要自己猜。</span></span>
<span class="line"><span>- 为每位有待办的参会者起草一封跟进邮件，放成草稿。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【边界】</span></span>
<span class="line"><span>- 不得发送邮件或消息，不得修改日历。</span></span>
<span class="line"><span>- 纪要存到 /workspace/会议/日期_会议名.md。</span></span></code></pre></div><h2 id="用法示例" tabindex="-1">用法示例 <a class="header-anchor" href="#用法示例" aria-label="Permalink to &quot;用法示例&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>附件是今天产品评审会的录音，按会后流程处理。</span></span></code></pre></div><h2 id="如何定制" tabindex="-1">如何定制 <a class="header-anchor" href="#如何定制" aria-label="Permalink to &quot;如何定制&quot;">​</a></h2><ul><li><strong>会议类型</strong>：周会、客户会、面试的纪要格式不同，可以分别写成三个技能。</li><li><strong>提醒</strong>：加一个例程&quot;每天下午 5 点检查纪要里明天到期的待办，提醒我&quot;。</li><li><strong>共享</strong>：如果需要把纪要发到团队频道，让它出 Slack 草稿，由你确认后发送。</li></ul>`,8)])])}const h=t(p,[["render",o]]);export{d as __pageData,h as default};
